package com.studybuddy.api.domain;
import jakarta.persistence.*;
import java.time.Instant;
@Entity @Table(name="study_sessions")
public class StudySession { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="group_id",nullable=false) private StudyGroup group; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by",nullable=false) private User createdBy; @Column(name="starts_at",nullable=false) private Instant startsAt; @Column(name="ends_at",nullable=false) private Instant endsAt; @Column(length=300) private String location; @Column(name="virtual_url",length=500) private String virtualUrl; @Column(length=1000) private String agenda; protected StudySession(){} public StudySession(StudyGroup g,User u,Instant start,Instant end,String location,String virtualUrl,String agenda){group=g;createdBy=u;startsAt=start;endsAt=end;this.location=location;this.virtualUrl=virtualUrl;this.agenda=agenda;} public Long getId(){return id;} public StudyGroup getGroup(){return group;} public Instant getStartsAt(){return startsAt;} public Instant getEndsAt(){return endsAt;} public String getLocation(){return location;} public String getVirtualUrl(){return virtualUrl;} public String getAgenda(){return agenda;} }
